    --bg-color: #0a0a0a;
    --surface-color: #1a1a1a;
    --accent-color: #ffffff;
    --text-primary: #f5f5f5;
    --text-secondary: #a0a0a0;
    --border-color: #333333;
    --btn-bg: #ffffff;
    --btn-text: #000000;
    --transition: all 0.3s ease;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-color);
    color: var(--text-primary);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.6;
    overflow-x: hidden;
}

/* Accessibility */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: var(--btn-text);
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

header {
    padding: 1.5rem 2rem;
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    background: rgba(10, 10, 10, 0.95);
    backdrop-filter: blur(10px);
    z-index: 50;
}

nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-links a {
    color: var(--text-primary);
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 1px;
    transition: var(--transition);
}

.nav-links a:focus, .icon-btn:focus, .cta-button:focus, .add-to-cart:focus {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

/* Custom Focus for elements that use box-shadow elsewhere */
.add-to-cart:focus {
    box-shadow: 0 0 0 2px var(--bg-color), 0 0 0 4px var(--accent-color);
    outline: none;
}

/* Scroll Snap */
html {
    scroll-behavior: smooth;
}

    display: flex;
    gap: 1rem;
    align-items: center;
}

.icon-btn {
    background: none;
    border: none;
    color: var(--text-primary);
    cursor: pointer;
    font-size: 1.2rem;
}

#menu-toggle {
    display: none;
}

/* Hero Section */
.hero {
    height: 80vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(rgba(0,0,0,0.4), rgba(0,0,0,0.4)), url('https://images.unsplash.com/photo-1512436991641-6745cdb1723f?auto=format&fit=crop&q=80&w=1200') center/cover;
    text-align: center;
    padding: 2rem;
}

.hero-content h1 {
    font-size: 4rem;
    margin-bottom: 1rem;
    letter-spacing: -1px;
}

.hero-content p {
    font-size: 1.2rem;
    max-width: 600px;
    margin: 0 auto 2rem;
    color: var(--text-secondary);
}

.cta-button {
    display: inline-block;
    background: var(--btn-bg);
    color: var(--btn-text);
    padding: 1rem 2.5rem;
    text-decoration: none;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 1px;
    transition: var(--transition);
}

.cta-button:hover {
    background: #e0e0e0;
    transform: translateY(-2px);
}

.cta-button.secondary {
    background: transparent;
    color: var(--text-primary);
    border: 1px solid var(--text-primary);
}

.cta-button.secondary:hover {
    background: var(--text-primary);
    color: var(--bg-color);
}

/* Sections General */
section {
    max-width: 1200px;
    margin: 4rem auto;
    padding: 0 2rem;
}

h2 {
    font-size: 2rem;
    margin-bottom: 2rem;
    text-align: center;
}

/* Deals Section */
.deals-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

.deal-card {
    background: var(--surface-color);
    padding: 3rem;
    border: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    transition: var(--transition);
}

.deal-card:hover {
    border-color: var(--text-secondary);
}

.deal-badge {
    background: #ff3e3e;
    color: white;
    padding: 0.2rem 0.8rem;
    font-size: 0.7rem;
    font-weight: bold;
    text-transform: uppercase;
    margin-bottom: 1rem;
}

.text-link {
    color: var(--text-primary);
    margin-top: 1rem;
    font-weight: 600;
}

/* Featured Products */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--surface-color);
    border: 1px solid var(--border-color);
    transition: var(--transition);
}

.product-card:hover {
    transform: translateY(-5px);
}

.product-image {
    height: 300px;
    background: #252525;
    background-size: cover;
    background-position: center;
}

.product-info {
    padding: 1.5rem;
    text-align: center;
}

.price {
    color: var(--text-secondary);
    margin: 0.5rem 0 1rem;
}

.add-to-cart {
    width: 100%;
    padding: 0.8rem;
    background: transparent;
    color: var(--text-primary);
    border: 1px solid var(--border-color);
    cursor: pointer;
    transition: var(--transition);
}

.add-to-cart:hover {
    background: var(--text-primary);
    color: var(--bg-color);
}

/* Editorial */
.editorial-layout {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.editorial-image {
    height: 500px;
    background: url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&q=80&w=800') center/cover;
}

.editorial-text h2 {
    text-align: left;
    margin-bottom: 1.5rem;
}

.editorial-text p {
    margin-bottom: 2rem;
    color: var(--text-secondary);
}

/* Footer */
footer {
    background: var(--surface-color);
    padding: 4rem 2rem 2rem;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: 4rem;
}

.footer-brand p {
    margin-top: 1rem;
    color: var(--text-secondary);
}

.footer-links h3 {
    margin-bottom: 1.5rem;
    font-size: 1rem;
}

.footer-links ul {
    list-style: none;
}

.footer-links li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--text-primary);
}

.footer-bottom {
    max-width: 1200px;
    margin: 4rem auto 0;
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.8rem;
}

/* Mobile Responsive */
@media (max-width: 768px) {
    .nav-links {
        display: none;
    }

    #menu-toggle {
        display: block;
    }

    .hero-content h1 {
        font-size: 2.5rem;
    }

    .deals-grid, .editorial-layout, .footer-grid {
        grid-template-columns: 1fr;
    }

    .editorial-layout {
        gap: 2rem;
    }

    .editorial-image {
        height: 300px;
    }
}
